def maxAverageOfPath(matrix):
    def dfs(x, y, path_sum, path_length):
        nonlocal max_avg
        if x == len(matrix) - 1 and y == len(matrix[0]) - 1:
            path_sum += matrix[x][y]
            path_length += 1
            avg = path_sum / path_length
            if avg > max_avg:
                max_avg = avg
            return
        if x < len(matrix) - 1:
            dfs(x + 1, y, path_sum + matrix[x][y], path_length + 1)
        if y < len(matrix[0]) - 1:
            dfs(x, y + 1, path_sum + matrix[x][y], path_length + 1)

    max_avg = float('-inf')
    dfs(0, 0, 0, 0)
    return max_avg

