["def maxAverageOfPath(matrix):
    n = len(matrix)
    dp = [[0] * n for _ in range(n)]

    # Initialize the first row and column
    for i in range(n):
        dp[0][i] = matrix[0][i]
        dp[i][0] = matrix[i][0]

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    # Calculate the total cost and number of cells visited
    total_cost = sum(sum(row) for row in dp)
    num_cells_visited = n * n

    # Calculate the average cost per cell
    max_average = total_cost / num_cells_visited

    return max_average", "def find_max_average(matrix):
    def dfs(x, y, path_cost, num_visited):
        nonlocal max_avg, total_cost, num_cells
        # Base case: if we reach the bottom-right cell
        if x == len(matrix) - 1 and y == len(matrix[0]) - 1:
            avg = path_cost / num_visited
            if avg > max_avg:
                max_avg = avg
            total_cost += path_cost
            num_cells += num_visited
            return
        # Recursive case: move right or down
        if x < len(matrix) - 1:
            dfs(x + 1, y, path_cost + matrix[x + 1][y], num_visited + 1)
        if y < len(matrix[0]) - 1:
            dfs(x, y + 1, path_cost + matrix[x][y + 1], num_visited + 1)

    max_avg = float('-inf')
    total_cost = 0
    num_cells = 0
