def extract_even(nested_tuple):
    def helper(tup):
        even_elements = []
        for item in tup:
            if isinstance(item, int):
                if item % 2 == 0:
                    even_elements.append(item)
            elif isinstance(item, tuple):
                even_elements.extend(helper(item))
        return tuple(even_elements)

    return helper(nested_tuple)

