["def extract_even(nested_tuple):
    def is_even(num):
        return num % 2 == 0

    def traverse_and_extract(tup):
        result = []
        for item in tup:
            if isinstance(item, int) and is_even(item):
                result.append(item)
            elif isinstance(item, tuple):
                result.extend(traverse_and_extract(item))
        return result

    odd_elements = traverse_and_extract(nested_tuple)
    # Reconstruct the tuple by replacing odd elements with None
    reconstructed_tuple = tuple(None if elem in odd_elements else elem for elem in nested_tuple)
    return reconstructed_tuple", "def extract_even_element(element):
    if isinstance(element, int) and element % 2 == 0:
