    elif isinstance(element, tuple):
        return sum([extract_even_element(sub_element) for sub_element in element], [])
    else:
        return []

def extract_even(nested_tuple):
    even_elements = []
    for element in nested_tuple:
        even_elements.extend(extract_even_element(element))
    return tuple(even_elements)

