def snake_to_camel(snake_str):
    camel_str = ''
    for i, char in enumerate(snake_str):
        if i > 0 and char.isupper():
            camel_str += '_' + char.lower()
        else:
            camel_str += char
    return camel_str

def snake_to_camel(snake_str):
    camel_str = ''
    for char in snake_str:
        if char.isupper():
            camel_str += char.lower()
        else:
            camel_str += char
    return camel_str

