def get_total_number_of_sequences(m, n):
    # Helper function to check if a sequence is valid
    def is_valid_sequence(seq):
        for i in range(1, len(seq)):
            if seq[i] < 2 * seq[i - 1] or seq[i] > m:
                return False
        return True

    # Initialize the DP table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There's one way to have a sequence of length 1 ending with any number
    for j in range(1, m + 1):
        dp[1][j] = 1

    # Fill the DP table
    for i in range(2, n + 1):
        for j in range(2, m + 1):
            for k in range(j // 2, j + 1):
                dp[i][j] += dp[i - 1][k]

    # The total number of valid sequences of length n
    return dp[n][m]

