def find_kth(arr1, arr2, k):
    i = j = 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] <= arr2[j]:
            if (i + j + 1) == k:
                return arr1[i]
            i += 1
        else:
            if (i + j + 1) == k:
                return arr2[j]
            j += 1
    if i == len(arr1):
        return arr2[k - i - 1]
    return arr1[k - j - 1]

