class TestDictDepth(unittest.TestCase):
    def test_dict_depth(self):
        self.assertEqual(dict_depth({'a':1, 'b': {'c': {'d': {}}}}), 4)
        self.assertEqual(dict_depth({'a':1, 'b': {'c':'python'}}), 2)
        self.assertEqual(dict_depth({1: 'Sun', 2: {3: {4:'Mon'}}}), 3)
        self.assertEqual(dict_depth({}), 0)
        self.assertEqual(dict_depth({'a':1}), 1)
        with self.assertRaises(ValueError):
            dict_depth({'a':1, 'b': {'c': {'d': {}}}})
        with self.assertRaises(ValueError):
            dict_depth({'a':1, 'b': {'c': {'d': {}, 'e': {}}}})
        with self.assertRaises(ValueError):
            dict_depth({'a':1, 'b': {'c': {'d': {}, 'e': {}}}, 'f': {'g': {'h': {}}}})

if __name__ == '__main__':
    unittest.main()"]

