["def lps(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    # Every single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table
    for length in range(2, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            if s[start] == s[end]:
                dp[start][end] = dp[start + 1][end - 1] + 2
            else:
                dp[start][end] = max(dp[start + 1][end], dp[start][end - 1])

    return dp[0][n - 1]", "def lps(s):
    n = len(s)
    max_length = 0
    start_index = 0

    for i in range(n):
        # Check for odd-length palindromes centered at s[i]
        left, right = i, i
        while left >= 0 and right < n and s[left] == s[right]:
            if right - left + 1 > max_length:
                max_length = right - left + 1
                start_index = left
            left -= 1
            right += 1

        # Check for even-length palindromes centered between s[i] and s[i+1]
        left, right = i, i + 1
        while left >= 0 and right < n and s[left] == s[right]:
            if right - left + 1 > max_length:
                max_length = right - left + 1
                start_index = left
            left -= 1
            right += 1

    return max_length", "def lps_recursive(s, i, j, memo):
    if i > j:
        return 0
    if i == j:
        return 1
    if s[i] == s[j]:
        memo[(i, j)] = 2 + lps_recursive(s, i+1, j-1, memo)
    else:
        memo[(i, j)] = max(lps_recursive(s, i+1, j, memo), lps_recursive(s, i, j-1, memo))
    return memo[(i, j)]

def lps(s):
    n = len(s)
    memo = {}
    return lps_recursive(s, 0, n-1, memo)

