def max_occurrences(lst):
    # Step 2: Initialize variables
    max_count = 0
    max_element = None

    # Step 3: Count occurrences using a dictionary
    occurrence_dict = {}
    for element in lst:
        if element in occurrence_dict:
            occurrence_dict[element] += 1
        else:
            occurrence_dict[element] = 1

    # Step 4: Find the element with the maximum occurrence
    for element, count in occurrence_dict.items():
        if count > max_count:
            max_count = count
            max_element = element

    # Step 5: Return the element with the maximum occurrence
    return max_element

