base_key:
def is_valid_parent(arr, i):
    # Check if the left child exists and is greater than the current node
    left_child = 2 * i + 1
    if left_child < len(arr) and arr[i] > arr[left_child]:
        return False

    # Check if the right child exists and is greater than the current node
    right_child = 2 * i + 2
    if right_child < len(arr) and arr[i] > arr[right_child]:
        return False

    return True

def check_min_heap(arr):
    for i in range(1, len(arr)):
        if not is_valid_parent(arr, i):
            return False

    return True

