def odd_length_sum(arr):
    total_sum = 0
    n = len(arr)
    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            if (j - i + 1) % 2 != 0:
                current_sum += arr[j]
        total_sum += current_sum
    return total_sum

