["def count_Occurrence(tuple_data, list_to_count):
    frequency_dict = {}

    for item in tuple_data:
        if item in frequency_dict:
            frequency_dict[item] += 1
        else:
            frequency_dict[item] = 1

    total_occurrences = sum(frequency_dict[item] for item in list_to_count)

    return total_occurrences", "def count_occurrences(elements, target_elements):
    # Initialize counters for each target element
    counts = {element: 0 for element in target_elements}

    # Count occurrences of each element in the elements list
    for element in elements:
        if element in counts:
            counts[element] += 1

    # Return counts for the target elements
    return {element: counts[element] for element in target_elements}

