    result = []
    for num in range(startnum, endnum + 1):
        str_num = str(num)
        if '0' in str_num:
            continue
        divisible = True
        for digit in str_num:
            if int(digit) == 0 or num % int(digit) != 0:
                divisible = False
                break
        if divisible:
            result.append(num)
    return result

