def divisors(num):
    """Returns a list of all divisors of num."""
    divs = [1]
    for i in range(2, int(sqrt(num)) + 1):
        if num % i == 0:
            divs.extend([i, num // i])
    return sorted(divs)

def amicable_numbers_sum(n):
    def is_amicable(a, b):
        return sum(divisors(a)) == b and sum(divisors(b)) == a

    amicable_numbers = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if is_amicable(i, j):
                amicable_numbers.append(i)
                break
    return sum(amicable_numbers)", null, null]

