def is_amicable(n):
    """
    Determine if a number is amicable.

    :param n: The number to check.
    :return: True if n is amicable, False otherwise.
    """
    def sum_of_divisors(num):
        # Helper function to find the sum of divisors of a number
        divisors = [1]
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                divisors.append(i)
                if i != num // i:
                    divisors.append(num // i)
        return sum(divisors)

    return sum_of_divisors(n) == n

def amicable_numbers_sum(limit):
    """
    Calculate the sum of all amicable numbers up to a given limit.

    :param limit: The upper limit of the range to search for amicable numbers.
    :return: The sum of all amicable numbers up to the limit.
    """
    total_sum = 0
    for num in range(1, limit + 1):
        if is_amicable(num):
            total_sum += num
    return total_sum

