    def max_sub_array_sum(nums):
        max_current = nums[0]
        max_global = nums[0]

        for num in nums[1:]:
            max_current = max(num, max_current + num)
            max_global = max(max_global, max_current)

        return max_global

    repeated_arr = arr * k
    return max_sub_array_sum(repeated_arr) * k

