def max_product(arr):
    if len(arr) < 2:
        return arr[0]

    max_subseq = [arr[0]]
    max_product_so_far = arr[0]

    for i in range(1, len(arr)):
        if arr[i] > max_subseq[-1]:
            max_subseq.append(arr[i])
        else:
            max_subseq = [arr[i]]

        current_product = 1
        for num in max_subseq:
            current_product *= num

        max_product_so_far = max(max_product_so_far, current_product)

    return max_product_so_far

