def merge_sorted_list(list1, list2, list3):
    merged_list = []
    while list1 or list2 or list3:
        min_value = float('inf')
        index = -1
        if list1:
            min_value = list1[0]
            index = 0
        if list2:
            if list2[0] < min_value:
                min_value = list2[0]
                index = 1
        if list3:
            if list3[0] < min_value:
                min_value = list3[0]
                index = 2

        if index == 0:
            merged_list.append(list1.pop(0))
        elif index == 1:
            merged_list.append(list2.pop(0))
        else:
            merged_list.append(list3.pop(0))

    return merged_list

